batch = db.batch()
count = 0
for rule in rules:
    rid = rule['id']
    # إضافة حقول النظام
    doc_data = {
        'id': rid,
        'source_group': 'municipal',
        'category': rid.split('-')[0],  # AUDIT, RISK, COMPLY, PAYROLL, HR, ENGINE
        'doc_type': 'municipal_rule',
        'data': rule,
        'created_at': datetime.now(timezone.utc).isoformat(),
        'updated_at': datetime.now(timezone.utc).isoformat()
    }
    db.collection('compliance_rules').document(rid).set(doc_data)
    count += 1
    if count % 400 == 0:
        batch.commit()
        batch = db.batch()
if count % 400 != 0:
    batch.commit()

print(f"✅ تم حقن {count} قاعدة بلدية جديدة في compliance_rules")
